    fromMip.VSSIP.valid -> fromMip.VSSIP.bits,
    fromHip.VSSIP.valid -> fromHip.VSSIP.bits,
    fromVSip.VSSIP.valid -> fromVSip.VSSIP.bits,
  ))
}
